#!/usr/bin/env python3 -I
"""Generates custom-sql/016_pet_standins.sql: the pet STAND-IN creature templates (9000000 + species) as plain idempotent SQL, so they exist BEFORE the first world start
(a fresh install then needs no extra restart). Same rules as EnsureStandIns in scripts/pb_battle.lua (that Lua stays as a harmless fallback). The column list is read from
information_schema at apply time, so a core update that adds a creature_template column cannot break it.
Usage (project root, from the host):  python3 -I pet-battle/gen_standins_sql.py     (re-run after the species list in pb_data.lua changes; needs luajit)"""
import subprocess, sys
ids = subprocess.run(["luajit", "-e", 'package.path="scripts/?.lua;"..package.path; local D=require("pb_data"); local t={} for s in pairs(D.species) do if D.StandIn(s) then t[#t+1]=s end end table.sort(t) print(table.concat(t,","))'],
                     capture_output=True, text=True, check=True).stdout.strip()
n = len(ids.split(","))
ZERO = "difficulty_entry_1 difficulty_entry_2 difficulty_entry_3 KillCredit1 KillCredit2 npcflag unit_flags unit_flags2 dynamicflags lootid pickpocketloot skinloot gossip_menu_id mingold maxgold VehicleId PetSpellDataId flags_extra rank MovementType type_flags".split()
sql = f"""-- GENERATED by pet-battle/gen_standins_sql.py - do not edit. Pet battle stand-in templates (entry 9000000 + species, {n} species): clones of the species' creature_template
-- (+ model rows + equipment) with no AI / script / flags / loot / gossip, faction 35, type 12 (non-combat pet) -> 1 so spells land. Idempotent (INSERT IGNORE).
USE acore_world;
SET SESSION group_concat_max_len = 1000000;
SET @pb_ids = '{ids}';
SET @pb_cols = (SELECT GROUP_CONCAT(CONCAT('`', COLUMN_NAME, '`') ORDER BY ORDINAL_POSITION SEPARATOR ',') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'creature_template');
SET @pb_sel = (SELECT GROUP_CONCAT(CASE
    WHEN COLUMN_NAME = 'entry' THEN 'src.`entry` + 9000000'
    WHEN COLUMN_NAME IN ('AIName', 'ScriptName') THEN '\\'\\''
    WHEN COLUMN_NAME = 'faction' THEN '35'
    WHEN COLUMN_NAME = 'type' THEN 'IF(src.`type` = 12, 1, src.`type`)'
    WHEN COLUMN_NAME IN ({",".join("'%s'" % c for c in ZERO)}) THEN '0'
    ELSE CONCAT('src.`', COLUMN_NAME, '`') END ORDER BY ORDINAL_POSITION SEPARATOR ',') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'creature_template');
SET @pb_q = CONCAT('INSERT IGNORE INTO creature_template (', @pb_cols, ') SELECT ', @pb_sel, ' FROM creature_template src WHERE FIND_IN_SET(src.`entry`, @pb_ids)');
PREPARE pb_stmt FROM @pb_q; EXECUTE pb_stmt; DEALLOCATE PREPARE pb_stmt;
UPDATE creature_template SET `type` = 1 WHERE entry >= 9000000 AND entry < 9100000 AND `type` = 12;
INSERT IGNORE INTO creature_template_model (CreatureID, Idx, CreatureDisplayID, DisplayScale, Probability, VerifiedBuild)
    SELECT CreatureID + 9000000, Idx, CreatureDisplayID, DisplayScale, Probability, VerifiedBuild FROM creature_template_model WHERE FIND_IN_SET(CreatureID, @pb_ids);
INSERT IGNORE INTO creature_equip_template (CreatureID, ID, ItemID1, ItemID2, ItemID3, VerifiedBuild)
    SELECT CreatureID + 9000000, ID, ItemID1, ItemID2, ItemID3, VerifiedBuild FROM creature_equip_template WHERE FIND_IN_SET(CreatureID, @pb_ids);
"""
open("custom-sql/016_pet_standins.sql", "w").write(sql)
print(f"custom-sql/016_pet_standins.sql written ({n} species)")
